int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int t;
    cin >> t;

    while (t--) {
        int n, k, d;
        cin >> n >> k >> d;

        vector<int> v(n);
        for (int& x : v) cin >> x;

        unordered_map<int, int> freq;
        freq.reserve(d * 2);

        int distinct = 0;
        for (int i = 0; i < d; ++i) {
            if (++freq[v[i]] == 1) ++distinct;
        }

        int answer = distinct;

        for (int i = d; i < n; ++i) {
            int outgoing = v[i - d];
            if (--freq[outgoing] == 0) {
                freq.erase(outgoing);
                --distinct;
            }

            if (++freq[v[i]] == 1) ++distinct;
            answer = min(answer, distinct);
        }

        cout << answer << '\n';
    }

    return 0;
}

